// 解析 webhook payload
const body = $input.item.json.body || $input.item.json;

// 处理 images 字段（支持数组或逗号分隔字符串）
let images = body.images || [];
if (typeof images === 'string') {
  images = images.split(',').map(s => s.trim()).filter(Boolean);
}

// 处理 tags 字段
let tags = body.tags || [];
if (typeof tags === 'string') {
  tags = tags.split(',').map(s => s.trim()).filter(Boolean);
}

return [{
  json: {
    title: body.title || '无标题',
    xhs_content: body.xhs_content || body.content || '',
    gzh_html: body.gzh_html || '',
    images: images,
    tags: tags,
    publish_time: body.publish_time || new Date().toISOString()
  }
}];

// 调用 xhs_publisher 发布小红书
const data = $input.first().json;

const payload = {
  title: data.title,
  content: data.xhs_content,
  images: data.images,
  tags: data.tags,
  cookies_json_path: '/data/shared/xhs_cookies.json'
};

let result;
try {
  // 使用 this.helpers.httpRequest，json 参数自动序列化为 JSON
  result = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://xhs-publisher:8000/publish',
    json: payload,
    timeout: 120000
  });
} catch(e) {
  result = { error: e.message, xhs_status: 'failed' };
}

return [{ json: { xhs_result: result } }];

// 汇总结果
const xhsResult = $input.first().json.xhs_result || {};
const xhsSuccess = xhsResult.status === 'success' || (!xhsResult.error && !xhsResult.xhs_status);

return [{
  json: {
    status: 'success',
    message: '🎉 发布流程已执行完成！',
    xhs: xhsSuccess ? '✅ 小红书发布成功' : ('⚠️ 小红书: ' + (xhsResult.error || JSON.stringify(xhsResult))),
    published_at: new Date().toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai' })
  }
}];
